-- Apply once after 118, then deploy the website. No bot restart required.
-- Only about_me_Pics/OFFICIAL APPROVAL.png is included. No folder upload,
-- storage bucket, generic media endpoint or access to other photos is created.
-- Source SHA256: 702e0722855c6261687786dfba9912bcac6bc86247c2e036571edcfc59142d4e
begin;
create table khub_bot.official_approval_image (
    id boolean primary key default true check(id),
    mime_type text not null default 'image/png' check(mime_type='image/png'),
    content bytea not null check(octet_length(content) between 1 and 2097152
        and substring(content from 1 for 8)=decode('89504e470d0a1a0a','hex'))
);
alter table khub_bot.official_approval_image enable row level security;
revoke all on khub_bot.official_approval_image from public,anon,authenticated,service_role;

insert into khub_bot.official_approval_image(id,content) values(true,decode(
    '','base64'));

-- This deliberately takes no filename, path or ID: only this approved image
-- can be read. Private appeal evidence and other photos retain their own rules.
create function public.read_official_approval_image() returns jsonb
language sql stable security definer set search_path='' as $$
    select jsonb_build_object('mime_type',mime_type,
        'base64',replace(encode(content,'base64'),E'\n',''))
    from khub_bot.official_approval_image where id;
$$;
revoke all on function public.read_official_approval_image() from public;
grant execute on function public.read_official_approval_image() to anon,authenticated,service_role;
notify pgrst,'reload schema';
commit;
